ALTER TABLE public.automazioni_conti ADD COLUMN liquidita_limite numeric, ADD COLUMN acquisto_limite numeric, ADD COLUMN limiti_conto_id text;
ALTER TABLE public.automazioni_conti ADD CONSTRAINT fondi_limiti_non_negativi CHECK ((liquidita_limite IS NULL OR liquidita_limite >= 0) AND (acquisto_limite IS NULL OR acquisto_limite >= 0)) NOT VALID;
CREATE TABLE public.registro_ordini (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, piattaforma text NOT NULL, ambiente text NOT NULL, conto_id text NOT NULL, client_id text NOT NULL, broker_id text, ticker text NOT NULL, lato text NOT NULL, strategia text NOT NULL, importo_richiesto numeric, stato text NOT NULL DEFAULT 'da_inviare', quantita_eseguita numeric NOT NULL DEFAULT 0, prezzo_medio numeric, eseguito_il timestamptz, riconciliato_il timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,piattaforma,ambiente,conto_id,client_id));
GRANT SELECT ON public.registro_ordini TO authenticated; GRANT ALL ON public.registro_ordini TO service_role;
ALTER TABLE public.registro_ordini ENABLE ROW LEVEL SECURITY;
CREATE POLICY registro_ordini_own ON public.registro_ordini FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE UNIQUE INDEX registro_ordini_broker_unique ON public.registro_ordini(user_id,piattaforma,ambiente,conto_id,broker_id) WHERE broker_id IS NOT NULL;
CREATE TABLE public.esecuzioni_broker (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, piattaforma text NOT NULL, ambiente text NOT NULL, conto_id text NOT NULL, broker_fill_id text NOT NULL, broker_order_id text NOT NULL, ticker text NOT NULL, lato text NOT NULL, quantita numeric NOT NULL, prezzo numeric NOT NULL, eseguito_il timestamptz NOT NULL, UNIQUE(user_id,piattaforma,ambiente,conto_id,broker_fill_id));
GRANT SELECT ON public.esecuzioni_broker TO authenticated; GRANT ALL ON public.esecuzioni_broker TO service_role;
ALTER TABLE public.esecuzioni_broker ENABLE ROW LEVEL SECURITY;
CREATE POLICY esecuzioni_broker_own ON public.esecuzioni_broker FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE TABLE public.istantanee_contabili (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, piattaforma text NOT NULL, ambiente text NOT NULL, conto_id text NOT NULL, valuta text NOT NULL, equity numeric, liquidita numeric, potere_acquisto numeric, posizioni jsonb NOT NULL DEFAULT '[]', storico jsonb NOT NULL DEFAULT '[]', flussi jsonb NOT NULL DEFAULT '[]', stato text NOT NULL, motivo text NOT NULL, scarto numeric, osservato_dal timestamptz NOT NULL, osservato_al timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.istantanee_contabili TO authenticated; GRANT ALL ON public.istantanee_contabili TO service_role;
ALTER TABLE public.istantanee_contabili ENABLE ROW LEVEL SECURITY;
CREATE POLICY istantanee_contabili_own ON public.istantanee_contabili FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE INDEX istantanee_latest ON public.istantanee_contabili(user_id,piattaforma,ambiente,conto_id,created_at DESC);
CREATE TABLE public.lease_conti (user_id uuid NOT NULL, piattaforma text NOT NULL, ambiente text NOT NULL, proprietario uuid NOT NULL, scade_il timestamptz NOT NULL, PRIMARY KEY(user_id,piattaforma,ambiente));
GRANT ALL ON public.lease_conti TO service_role;
ALTER TABLE public.lease_conti ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.prendi_lease_conto(p_user uuid,p_piattaforma text,p_ambiente text,p_proprietario uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n integer; BEGIN INSERT INTO public.lease_conti(user_id,piattaforma,ambiente,proprietario,scade_il) VALUES(p_user,p_piattaforma,p_ambiente,p_proprietario,now()+interval '10 minutes') ON CONFLICT(user_id,piattaforma,ambiente) DO UPDATE SET proprietario=EXCLUDED.proprietario,scade_il=EXCLUDED.scade_il WHERE lease_conti.scade_il < now(); GET DIAGNOSTICS n = ROW_COUNT; RETURN n=1; END; $$;
REVOKE ALL ON FUNCTION public.prendi_lease_conto(uuid,text,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prendi_lease_conto(uuid,text,text,uuid) TO service_role;